import {entityGraph} from './entity-node.js';
import {caseListPage,casePage,caseReportPreview} from './case-workflow.js';
import {state,current,busy,roles,routeForFeature,flowRoutes} from './state.js';
import {pages,features,flows} from './requirements.js';
import {esc,icon,btn,link,tag,badge,field,select,area,check,empty,note,heading,table,section,kv,progress,steps} from './ui.js';
export const titleFor=id=>pages.find(p=>p.id===id)?.name||'研判助手';
export const statusLabel=s=>!s?'未开始':s.stopRequested?'停止处理中':({Clarification:'待澄清',Planning:'待确认计划',Execution:'执行中',Permission:'等待授权',Paused:'已暂停',Completed:'已完成',PartialSuccess:'部分成功',Failed:'失败',Terminated:'已终止'}[s.stage]||s.stage);
export const menus={overview:[['PG02','全域态势','chart'],['PG03','指标与警情明细','database']],search:[['PG04','新建搜索','plus'],['PG06','搜索历史','clock'],['PG05','当前工作台','search'],['PG09','资金流分析','chart'],['PG10','人员流分析','user'],['PG11','警情数据库问答','database'],['PG18','执行工作空间','folder'],['PG19','文档空间','file'],['PG20','关系导图','graph'],['PG23','事件时间线','clock'],['PG24','研判报告','file']],cases:[['PG12','因案研判','briefcase'],['PG14','因事研判','search'],['PG17','案件串并','graph']],admin:[['PG26','我的申请','shield'],['PG27','审批待办','check'],['PG28','通知与更新','bell'],['PG29','用户组织与权限','user'],['PG30','工具目录','settings'],['PG31','项目与Agent配置','graph'],['PG32','审计与运行诊断','shield'],['PG33','经验与偏好','file'],['PG34','Skills目录','folder']]};
export function groupFor(id){return ['PG02','PG03'].includes(id)?'overview':['PG12','PG13','PG14','PG15','PG16','PG17'].includes(id)?'cases':Number(id.slice(2))>=26?'admin':'search'}
export function header(id){const group=groupFor(id);return `<header class="header"><a href="#/PG05" class="brand"><img class="brand-mark" src="/assets/brand/logo.svg" alt=""><span>研判助手</span></a><nav class="global-nav" aria-label="一级导航">${[['overview','PG02','全域态势'],['search','PG05','超级搜索'],['cases','PG12','案件研判'],['admin','PG29','系统管理']].map(([g,p,t])=>link(t,p,g===group?'active':'')).join('')}</nav><div class="header-end"><button class="btn ghost context" data-action="context">${esc(state.caseId?'关联案件 · '+state.caseId:'未关联案件')}</button>${btn(icon('bell'),'notifications','aria-label="通知与更新"','ghost icon-only')}${btn(icon('sun'),'theme','aria-label="切换浅深主题"','ghost icon-only hide-mobile')}<button class="avatar" data-action="profile" aria-label="用户和角色设置">研</button></div></header><div class="prototype-bar"><span>${tag('交互原型','blue')} <span class="proto-long">仅合成数据 · 不连接真实业务系统</span><span class="detail-label"> · ${esc(state.org)} / ${esc(state.role)}</span></span><div class="actions"><select aria-label="页面状态演示" class="state-toggle" id="view-state">${['正常','加载中','空状态','加载失败','无权限','数据过期'].map(x=>`<option ${state.viewState===x?'selected':''}>${x}</option>`).join('')}</select>${btn('演示控制','demo','','ghost')}${btn('功能总览 34','coverage','','ghost')}</div></div>`}
export function sidebar(id){return `<aside class="module-sidebar"><h2>${({overview:'数据与线索',search:'研判工作空间',cases:'案件研判',admin:'管理与治理'})[groupFor(id)]}</h2>${menus[groupFor(id)].map(([p,t,i])=>link(icon(i)+t,p,(p===id||p==='PG12'&&id==='PG13'||p==='PG14'&&['PG15','PG16'].includes(id))?'active':'')).join('')}</aside>`}
export function genericState(){if(state.viewState==='正常')return '';if(state.viewState==='加载中')return `<div class="panel" role="status"><h2>正在加载页面快照</h2><div class="loading-line"></div><div class="loading-line"></div><div class="loading-line"></div>${btn('完成模拟加载','normal','','primary')}</div>`;return `<div class="panel">${empty(state.viewState==='空状态'?'当前范围暂无数据':state.viewState==='加载失败'?'页面加载失败':state.viewState==='无权限'?'当前无访问权限':'当前数据快照已过期',state.viewState==='无权限'?'未显示业务内容。请检查组织和角色，或按规定申请所需范围。':'这是页面状态演示，不会清除已保存的任务或草稿。',btn(state.viewState==='无权限'?'查看申请入口':'恢复正常视图',state.viewState==='无权限'?'access-route':'normal','','primary'))}</div>`}
export function denied(id){const restricted=['PG27','PG30','PG31','PG32','PG33','PG34'];const allow={PG27:['审批人员','业务负责人'],PG30:['平台管理员'],PG31:['平台管理员'],PG32:['安全审计人员','平台管理员'],PG33:['业务负责人','平台管理员'],PG34:['平台管理员']};if(!state.permission&&id!=='PG29'&&id!=='PG26')return true;if(state.org!=='演示研判一组'&&!['PG29','PG26','PG28','PG01'].includes(id))return true;if(restricted.includes(id))return !allow[id].includes(state.role);if(['平台管理员','安全审计人员'].includes(state.role)&&['PG02','PG03','PG04','PG06','PG07','PG11','PG15','PG18','PG05','PG08','PG09','PG10','PG12','PG13','PG14','PG16','PG17','PG19','PG20','PG21','PG22','PG23','PG24','PG25'].includes(id))return true;return false}
export function permissionPage(){return note('当前角色或组织无权访问此业务内容。原型在渲染前阻断展示；真实授权仍必须由服务端实现。','warning')+empty('当前无访问权限','可以切回演示研判一组并选择适当演示角色，或从我的申请发起授权申请。',btn('切换演示身份','profile','','primary')+' '+link('我的申请','PG26'))}
function planCard(s){if(s.stage==='Clarification')return `<div class="workflow-card"><div class="workflow-top"><strong>先确认研判范围</strong>${tag('需要你的确认','warning')}</div><p class="small">仅补充完成本次任务必要的信息，不自动扩大查询范围。</p><form id="clarify-form"><div class="grid-2">${select('分析场景','type',['人员流','资金流','警情问答'],s.type)}${field('目标实体或账户','target',s.type==='资金流'?'演示账户A':'演示对象甲','text','required maxlength="80"')}</div><div class="grid-2">${field('开始日期','start','2026-08-20','date','required')}${field('结束日期','end','2026-09-19','date','required')}</div>${select('来源范围','source',['已授权来源','需要扩展授权'], '已授权来源')}${check('我已核对稳定标识，非仅凭同名确认主体','confirmed',false,'required')}<div class="form-error" role="alert"></div><button class="btn primary" type="submit">确认范围并生成计划 ${icon('arrow')}</button></form></div>`;
 if(s.stage==='Planning')return `<div class="workflow-card"><div class="workflow-top"><strong>研判计划 · v${s.planVersion}</strong>${tag('尚未执行','blue')}</div><p class="small">${esc(s.scope)}</p><ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${note('仅访问授权范围；新增范围需再次授权。确认计划后才开始模拟执行。')}<div class="actions">${btn('确认并执行','confirm-plan','','primary','play')}${btn('调整计划','edit-plan')}</div></div>`;return ''}
function resultLinks(s){return `<div class="actions">${link('查看分析结果 '+icon('arrow'),s.type==='资金流'?'PG09':s.type==='警情问答'?'PG11':'PG10','btn primary')}${link('核验来源','PG22','btn')}${btn('生成报告','generate-report','','secondary','file')}</div>`}
export function workbench(id){const s=id==='PG04'?null:current();return `<main id="main" class="workbench"><aside class="search-sidebar"><div><h2>搜索会话</h2><p class="side-caption">历史会话与检索计划</p></div>${btn('新建搜索','new-search','','full','plus')}<label class="search-input">${icon('search')}<input id="side-search" aria-label="搜索历史会话" placeholder="搜索历史会话"></label><div id="side-sessions">${state.sessions.filter(x=>x.org===state.org&&!x.archived).slice(0,3).map(x=>`<button class="session-tile ${s?.id===x.id?'active':''}" data-action="open-session" data-id="${x.id}"><strong>${esc(x.title)}</strong><span class="small muted">${esc(x.type)} · ${esc(x.caseId||'未关联案件')}</span>${s?.id===x.id?progress(s.step/4*100):''}</button>`).join('')}</div>${link('查看全部历史 '+icon('chevron'),'PG06','small')}<div><div class="section-title"><h2>检索计划</h2>${s?`<span class="small" style="color:var(--brand)">${s.step} / 4 完成</span>`:''}</div>${s?`<div class="plan-list">${s.steps.map((x,i)=>`<button class="plan-step ${i<s.step?'done':i===s.step?'active':''}" data-action="step-detail" data-step="${i}">${icon(i<s.step?'check':'search')}<span>${String(i+1).padStart(2,'0')} ${esc(x)} · ${i<s.step?'已完成':i===s.step?statusLabel(s):'待开始'}</span></button>`).join('')}</div>`:`<p class="side-caption">发送问题后，在这里确认计划并跟踪真实步骤。</p>`}</div><div class="side-bottom"><span class="dot" style="${state.network?'':'background:var(--amber)'}"></span>${state.network?'本地快照已保存':'连接中断 · 保留最后快照'}<div class="small">${s?`会话 ${esc(s.id)} · seq ${s.seq}`:'演示模式 · 无外部工具调用'}</div></div></aside><section class="search-center"><div class="conversation-head"><div><h1>${s?'超级搜索':'新建搜索'}</h1><p>${s?esc(s.id)+' · '+esc(s.type):'从一个问题开始，让线索有据可查'}</p></div><div class="actions">${s?badge(statusLabel(s)):''}${s&&busy(s)?btn('停止执行','stop','', 'small','stop'):''}${btn(icon('menu'),'search-menu','aria-label="搜索导航"','ghost icon-only mobile-label')}${btn(icon('folder'),'workspace-drawer','aria-label="打开工作空间"','ghost icon-only layout-toggle')}</div></div><div class="messages" id="messages">${!state.network?note('连接中断，后台任务可能仍在执行。恢复时同步快照，不重发原消息。 '+btn('重新连接','reconnect','','small'),'warning'):''}${s?s.messages.map(m=>`<div class="message ${m.role}"><div class="avatar">${m.role==='user'?'我':'研'}</div><div class="bubble">${m.role==='assistant'?'<div class="caption">研判助手 · '+(s.state==='DONE'?'结果摘要':'阶段性结果，待核验')+'</div>':''}${esc(m.text)}</div></div>`).join('')+planCard(s)+(s.events.length?`<div class="workflow-card"><div class="workflow-top"><span>${icon('user')} <strong>${esc(s.type)}分析 Agent</strong></span>${badge(statusLabel(s))}</div><button class="tool-row" data-action="execution">${icon('file')}<span>${s.events.length} 次工具调用 · attempt ${s.attempt}</span>${icon('chevron')}</button><div class="spacer"></div><p class="small">${esc(s.steps[Math.min(s.step,3)])} · ${s.state==='DONE'?'查看核验结果':'阶段性发现不代替最终结论'}</p></div>`:'')+s.events.slice(-2).map(e=>`<div class="workflow-card"><div class="workflow-top"><strong>${icon('search')} ${esc(e.title)}</strong>${badge(e.status)}</div>${kv({'输入':'稳定对象ID · 授权范围','输出':esc(e.output),'工具版本':`${esc(e.tool)} / v${esc(e.version)}`})}</div>`).join('')+(s.stage==='Permission'?`<div class="workflow-card">${note('当前动作等待授权，其他未授权来源不会自动尝试。','warning')}${btn('申请访问权限','apply-permission','','primary')}</div>`:'')+(s.stage==='Failed'?`<div class="workflow-card">${note(esc(s.error),'danger')}<div class="actions">${btn('仅重试失败动作','retry','','primary')}${btn('重新规划','replan')}${btn('保留部分结果','partial')}</div></div>`:'')+(s.state==='PAUSED'&&s.stage!=='Terminated'?`<div class="workflow-card">${note('已在安全动作边界保存模拟检查点。恢复前重验组织、权限与范围。')}${btn('检查并恢复','resume','','primary')}</div>`:'')+(s.state==='DONE'?`<div class="workflow-card"><div class="workflow-top"><strong>本次产物与下一步</strong>${badge(statusLabel(s))}</div>${resultLinks(s)}</div>`:''):`<div class="welcome"><img class="brand-mark" src="/assets/brand/logo.svg" alt=""><h2>把问题交给研判，让结论回到证据。</h2><p>描述你的目标，确认范围与计划，跟踪每一步执行。<br>所有演示结果均可追溯到合成来源。</p><div class="starter-grid">${[['资金流','chart','核查演示账户A近30天交易，追踪多跳资金路径'],['人员流','user','核查演示对象甲近30天轨迹，并分析时空冲突'],['警情问答','database','统计演示辖区近30天各类别警情数量'],['简单问答','file','什么是研判报告中的数据缺口？']].map(([t,i,q])=>`<button class="starter" data-action="starter" data-type="${t}" data-question="${q}">${icon(i)}<strong>${t}</strong><p>${q}</p></button>`).join('')}</div><p class="small inset">${icon('shield')} 请勿在原型中输入真实案件、身份或敏感业务信息。</p></div>`}</div><form class="composer" id="composer-form"><div class="composer-inner"><textarea id="prompt" name="prompt" rows="1" maxlength="2000" aria-label="研判问题" placeholder="输入搜索问题，或补充检索条件">${esc(s?s.draft:(state.newDraft||''))}</textarea>${btn(icon('external'),'expand-input','aria-label="展开编辑问题"','ghost icon-only')}${btn(icon('upload')+'<span class="upload-label">上传材料</span>','upload','','ghost') }<button class="btn primary icon-only" type="submit" aria-label="发送研判问题" ${(s&&busy(s))||!(s?s.draft:(state.newDraft||'')).trim()?'disabled':''}>${icon('send')}</button></div><div class="hint">${s&&busy(s)?'执行中可编辑草稿；完成或停止确认后发送':'Enter 发送 · Shift+Enter 换行 · 中文输入法组合态不发送'} · 仅合成数据</div></form></section>${workspace('工作空间')}</main>`}
export function workspace(tab='工作空间'){const s=current();return `<aside class="right-panel"><div class="tabs" role="tablist" aria-label="工作空间标签">${['工作空间','文档空间','导图空间'].map(x=>`<button role="tab" aria-selected="${x===tab}" class="${x===tab?'active':''}" data-action="workspace-tab" data-tab="${x}">${x}</button>`).join('')}</div><div class="right-content">${tab==='工作空间'?section('执行概览',s?`<div class="status-box"><div class="status-symbol">${icon(s.state==='DONE'?'check':'clock')}</div><div><strong>${statusLabel(s)}</strong><p class="small">${esc(s.type)} Agent · ${s.step}/4 步骤完成</p></div></div>`:empty('等待发起任务','任务计划和执行状态将在这里同步。'),'<span class="small muted">本地模拟</span>')+section('执行结构',s?`<div class="tree-row"><div class="grow"><p>主任务</p><strong>${esc(s.title)}</strong></div><span>${s.step}/4 完成</span></div><div class="tree-row"><div><p>子任务</p>${esc(s.steps[Math.min(s.step,3)])}</div>${badge(statusLabel(s))}</div><div class="tree-row"><div><p>执行智能体</p>${esc(s.type)}分析 Agent</div>${link('查看轨迹','PG08')}</div>`:'<p class="small muted">发送后生成任务和产物。</p>')+section('实体焦点',state.entities.slice(0,2).map(e=>`<button class="entity-row" data-action="entity" data-id="${e.id}">${icon('user')}<div class="grow"><strong>${esc(e.name)}</strong><p class="small">${esc(e.type)} · ${e.id}</p></div>${icon('chevron')}</button>`).join(''))+section('最近材料',state.files.filter(f=>f.org===state.org&&!f.archived).slice(0,3).map(f=>fileRow(f)).join(''),link('查看全部','PG19','small')):tab==='文档空间'?section('任务产物',state.files.filter(f=>f.org===state.org&&!f.archived).map(fileRow).join(''),btn('上传','upload','','small','upload'))+note('原始文件与派生结果分别保留。预览中可查看来源任务与版本。')+link('展开文档空间','PG19','btn full'):graph(true)+`<div class="spacer"></div>${note('实线为来源事实，虚线为待核验推断。关系不是违法概率。')}${link('展开导图空间','PG20','btn full')}`}</div></aside>`}
function fileRow(f){return `<button class="file-row" data-action="preview-file" data-id="${f.id}">${icon('file')}<div class="grow">${esc(f.name)}<p class="small">${f.raw?'原始材料':'派生产物'} · v${f.version}</p></div>${badge(f.status)}</button>`}
export function graph(compact=false){
 let reachable=null;
 if(state.pathDepth){reachable=new Set(['E-002']);for(let i=0;i<parseInt(state.pathDepth);i++){const next=new Set(reachable);for(const e of state.relations){if(reachable.has(e.from))next.add(e.to);if(reachable.has(e.to))next.add(e.from)}reachable=next}}
 const nodes=state.entities.filter(e=>!e.hidden&&(!reachable||reachable.has(e.id))).map((e,i)=>({...e,x:28+(i%3)*300,y:60+Math.floor(i/3)*190}));
 const links=state.relations.map(r=>({...r,label:r.type,inferred:r.source.includes('推断')}));
 return `<div class="graph-canvas">${compact?'':`<div class="graph-toolbar">${btn('添加实体','add-entity','','small','plus')}${btn('补充关系','add-relation','','small','graph')}${btn('恢复上一版本','graph-undo',state.graphHistory.length?'':'disabled','small','refresh')}${btn('重置视图','graph-reset','','small')}${tag('图谱 v'+state.graphVersion)}${state.pathDepth?tag('账户A · '+state.pathDepth+'关联范围'):''}</div>`}${entityGraph(nodes,links,{id:compact?'workspace-preview':'workspace',width:Math.max(330,Math.min(nodes.length,3)*300),height:Math.max(280,Math.ceil(nodes.length/3)*190+70),ui:state.graphUI?.[compact?'workspace-preview':'workspace']||{}})}</div>`;
}

function metric(label,value,sub,action='drill'){return `<button class="metric" data-action="${action}" data-metric="${label}"><label>${label}</label><strong>${value}</strong><small>${sub} ${icon('chevron')}</small></button>`}
function chart(){return `<div class="chart-bars" aria-label="近7天合成警情趋势：18、24、19、32、27、35、29条">${[18,24,19,32,27,35,29].map((v,i)=>`<div class="bar-group"><button title="9月${13+i}日：${v}条（合成）" aria-label="9月${13+i}日 ${v}条，查看明细" style="height:${v/40*100}%" data-action="drill" data-metric="9月${13+i}日 · ${v}条"></button><span>09/${13+i}</span></div>`).join('')}</div>`}
function overview(){return heading('全域态势','从变化中发现线索，所有指标均可回到统计口径与来源。',btn('保存当前视图','favorite','','secondary','plus'),'态势总览 / R2 交互预览')+`<form id="overview-filter" class="filter-bar">${field('开始日期','start',state.filters.start||'2026-08-20','date','required')}${field('结束日期','end',state.filters.end||'2026-09-19','date','required')}${select('地域','region',['演示辖区','演示片区一','演示片区二'],state.filters.region||'演示辖区')}${select('类别','category',['全部类别','涉网线索','资金线索','其他线索'],state.filters.category||'全部类别')}<button class="btn primary" type="submit">应用筛选</button>${btn('重置','reset-filters')}<div class="form-error" role="alert"></div></form>${note('合成数据快照 · 2026-09-19 14:30 · UTC+8 · 按 alert_id 去重。指标为固定合成样本，不代表真实警情。日期与地域仅用于预览查询条件；未连接数据源，不据此重新计算趋势。')}${state.favorites.length?`<div class="actions inset">已保存视图：${state.favorites.map((x,i)=>btn(esc(x.name||('视图 '+(i+1))),'load-favorite',`data-id="${x.id}"`,'small')).join('')}</div><div class="spacer"></div>`:''}<div class="metric-grid">${metric('授权范围内警情',({'涉网线索':'82','资金线索':'62','其他线索':'40'})[state.filters.category]||'184','条 · 查看去重明细')}${metric('待核验线索','12','条 · 非案件定性')}${metric('数据来源覆盖','3 / 4','1个来源尚未接入')}${metric('同期变化','—','同期数据缺失，不计算增幅')}</div><div class="grid-2">${section('近7天趋势',chart()+table(['日期','数量（条）'],[['09/17','27'],['09/18','35'],['09/19','29']],'图表数据替代视图'),btn('查看口径','metric-definition','','small'),'panel')}${section('类别分布',table(['类别','数量','操作'],[['涉网线索','82',btn('查看明细','drill','data-metric="涉网线索"','small')],['资金线索','62',btn('查看明细','drill','data-metric="资金线索"','small')],['其他线索','40',btn('查看明细','drill','data-metric="其他线索"','small')]])+`<div class="spacer"></div>${note('地域坐标未接入，使用数据表替代地图，不使用默认坐标伪造分布。')}`,'','panel')}</div>`}
export function drill(){return heading('态势明细','承接筛选快照，核验后可将条件带入新的研判任务。',btn('带条件发起研判','drill-search','','primary','search'),'PG03 · 态势钻取')+note(`当前范围：${esc(state.filters.start||'2026-08-20')} 至 ${esc(state.filters.end||'2026-09-19')} · ${esc(state.filters.region||'演示辖区')} · ${esc(state.filters.category||'全部类别')}。新任务发送前仍需确认范围。`)+table(['记录ID','类别','时间 UTC+8','来源','操作'],[['DEMO-001','涉网线索','2026-09-19 10:12','合成来源 S01',btn('查看来源','evidence','','small')],['DEMO-002','资金线索','2026-09-18 16:40','合成来源 S02',btn('查看来源','evidence','','small')],['DEMO-003','其他线索','2026-09-17 09:20','合成来源 S03',btn('查看来源','evidence','','small')]])+`<div class="table-footer">原型展示3条合成明细，不代表完整184条数据 ${btn('统计口径','metric-definition','','small')}</div>`}
function history(){const list=state.sessions.filter(s=>s.org===state.org&&(!state.historyFilter||s.title.includes(state.historyFilter))&&(!state.historyStart||s.updated.slice(0,10)>=state.historyStart)&&(!state.historyCase||state.historyCase==='全部'||s.caseId===state.historyCase)&&(state.historyStatus==='全部'||(state.historyStatus==='已归档'?s.archived:!s.archived&&statusLabel(s)===state.historyStatus)));return heading('搜索历史','恢复已有会话和阅读位置，不重新执行历史动作。',btn('新建搜索','new-search','','primary','plus'))+`<form id="history-filter" class="filter-bar">${field('搜索标题','query',state.historyFilter,'search','placeholder="输入会话标题"')}${field('更新日期起','start',state.historyStart||'','date')}${select('案件上下文','caseId',['全部',...state.cases.map(c=>c.id)],state.historyCase||'全部')}${select('状态','status',['全部','执行中','已完成','失败','已归档'],state.historyStatus)}<button class="btn" type="submit">筛选</button>${btn('清空条件','clear-history')}</form>`+table(['会话','场景','状态','最近更新','操作'],list.slice(((state.historyPage||1)-1)*10,(state.historyPage||1)*10).map(s=>[btn(esc(s.title),'open-session',`data-id="${s.id}"`,'ghost'),esc(s.type),badge(s.archived?'已归档':statusLabel(s)),esc(s.updated),`<div class="actions">${btn('重命名','rename-session',`data-id="${s.id}"`,'small')}${btn(s.archived?'取消归档':'归档','archive-session',`data-id="${s.id}" `,'small')}</div>`]))+`<div class="table-footer">共 ${list.length} 条 · 名称不作为唯一ID<div class="actions">${btn("上一页","history-page",`data-page="${(state.historyPage||1)-1}" ${(state.historyPage||1)<=1?"disabled":""}`,"small")}<span>第 ${state.historyPage||1} 页</span>${btn("下一页","history-page",`data-page="${(state.historyPage||1)+1}" ${(state.historyPage||1)*10>=list.length?"disabled":""}`,"small")}</div></div>`}
export function execution(){const s=current();if(!s)return empty('暂无执行任务','新建搜索并确认计划后，执行轨迹会在这里出现。',link('新建搜索','PG04','btn primary'));return heading('执行详情',`${s.id} · attempt ${s.attempt} · plan v${s.planVersion}`,`<div class="actions">${badge(statusLabel(s))}${s.state==='RUNNING'?btn('安全暂停','pause','','secondary','pause'):''}${s.state==='PAUSED'&&s.stage!=='Terminated'?btn('检查并恢复','resume','','primary','play'):''}${busy(s)?btn('停止任务','stop','','danger','stop'):''}${s.stage==='Failed'?btn('局部重试','retry','','primary','refresh'):''}</div>`,'任务 / 动作 / 工具')+note('原型采用可控模拟事件；不展示模型原始思维链。工具输入仅展示脱敏摘要，保留版本和结果引用。')+`<div class="grid-3"><div class="panel">${kv({'Task ID':esc(s.taskId||s.id+'-T1'),'父任务':esc(s.parentTaskId||'—'),'TaskState':tag(s.state),'展示阶段':badge(s.stage),'步骤进度':s.step+'/4'})}</div><div class="panel">${kv({'计划版本':'v'+s.planVersion,'执行尝试':String(s.attempt),'最后事件序号':String(s.seq)})}</div><div class="panel">${kv({'关联案件':esc(s.caseId||'未关联'),'组织':esc(s.org),'模拟连接':state.network?'在线':'断线'})}</div></div><div class="spacer"></div>`+table(['步骤 / 动作','ActionStatus','工具版本','耗时','输入与输出'],s.events.map(e=>[esc(e.title),badge(e.status),esc(e.tool)+' / v'+esc(e.version),e.duration,btn('查看详情','tool-event',`data-id="${e.id}"`,'small')]))+`<div class="spacer"></div><div class="actions">${btn('推进一步模拟事件','advance',s.state==='RUNNING'?'':'disabled','primary')}${btn('重新规划','replan')}${btn('收取已有部分结果','partial',s.step>0&&!busy(s)?'':'disabled')}${link('回到超级搜索','PG05','btn')}</div>`}
function fund(){return heading('资金流分析','分别核对账户、币种、冲正与来源，异常模式只是待核验线索。',btn('发起资金分析','start-fund','','primary','search'),'专项分析 / R1')+`<form class="filter-bar" id="fund-filter">${field('账户稳定标识','account',state.fundAccount||'DEMO-ACCOUNT-A','text','required')}${select('币种','currency',['CNY','USD'],state.fundCurrency||'CNY')}${select('交易状态','status',['全部','有效','冲正'],state.fundStatus||'全部')}<button class="btn" type="submit">更新统计</button></form>${note('合成交易共4条；按交易ID去重。CNY收入冲正2000元单列，不混入有效流出。无USD数据时不换算或合计。')}<div class="metric-grid">${metric('有效流出',(state.fundCurrency==='USD'||state.fundAccount&&state.fundAccount!=='DEMO-ACCOUNT-A')?'0':'20,000.00',(state.fundCurrency||'CNY')+' · 有效交易','fund-definition')}${metric('冲正金额',(state.fundCurrency==='USD'||state.fundAccount&&state.fundAccount!=='DEMO-ACCOUNT-A')?'0':'2,000.00',(state.fundCurrency||'CNY')+' · 冲正单列','fund-definition')}${metric('交易对手',(state.fundCurrency==='USD'||state.fundAccount&&state.fundAccount!=='DEMO-ACCOUNT-A')?'0':'2','合成标识去重','fund-definition')}${metric('可追踪深度','2 跳','仅授权数据范围','fund-definition')}</div><div class="split">${section('交易明细',table(['交易ID','收款对象','金额 / CNY','状态','来源'],(state.fundCurrency==='USD'||state.fundAccount&&state.fundAccount!=='DEMO-ACCOUNT-A')?[]:[['T001','演示商户B','12,000.00','有效',btn('S02 / 第2行','evidence','','small')],['T002','演示商户B','5,000.00','有效',btn('S02 / 第3行','evidence','','small')],['T003','演示账户C','3,000.00','有效',btn('S02 / 第4行','evidence','','small')],['T004','演示账户A','2,000.00','冲正',btn('S02 / 第5行','evidence','','small')]].filter(r=>!state.fundStatus||state.fundStatus==='全部'||r[3]===state.fundStatus)),btn('导出CSV','export-transactions','','small','download'))}${section('资金路径',graph(true)+`<div class="spacer"></div>${note('演示账户A → 演示商户B。路径表示可核验往来，不等于控制关系或违法判断。')}${btn('多跳追踪','fund-path','','secondary','graph')}`)}</div><div class="actions">${btn('生成资金报告','generate-report','data-type="资金流"','primary')}${btn('围绕此结果继续研判','follow-result','data-type="资金流"')}${link('核验来源','PG22','btn')}</div>`}
function person(){return heading('人员流分析','先确认主体，再统一时间和位置精度；冲突记录并列保留。',btn('发起人员分析','start-person','','primary','search'),'专项分析 / R1')+note('演示对象甲 · 稳定标识 DEMO-PERSON-001。姓名不是唯一标识；全部时间统一为UTC+8。')+`<div class="split"><div>${section('身份与关系背景',kv({'实体':btn('演示对象甲','entity','data-id="E-001"','ghost'),'稳定标识':'DEMO-PERSON-001','主体核验':'合成来源 S01；同名对象另行确认','角色':'关联人（来自演示资料，不是模型定性）'}),'','panel')}${section('活动轨迹',`<div class="timeline"><div class="timeline-item"><small>2026-09-03 10:20 · UTC+8</small><strong>演示地点C</strong><p>合成来源S03 · 城区级精度 · 原始时间已保留</p>${btn('定位原始记录','evidence','','small')}</div><div class="timeline-item"><small>2026-09-03 10:25 · UTC+8</small><strong>演示地点D</strong><p>合成来源S04 · 场所级精度 · 待核验主体一致性</p>${btn('核验时空冲突','conflict','','small')}</div></div>`,'','panel')}</div><div>${section('待核验事项',note('两条记录在短时间窗口出现位置差异，可能是身份、采集时间或精度问题，不直接推定不可能移动。','warning')+btn('查看冲突详情','conflict','','primary')+`<div class="spacer"></div>${kv({'来源覆盖':'2个合成来源','精度约束':'城区级与场所级不可直接等同','地图状态':'无地图连接器，使用轨迹表替代','结论状态':'待人工来源核验'})}`,'','panel')}${section('研判延展',`<div class="stack">${btn('在时间线中对照','go-timeline','','secondary','clock')}${btn('查看关系导图','go-graph','','secondary','graph')}${btn('生成报告','generate-report','data-type="人员流"','primary','file')}${btn('继续追问','follow-result','data-type="人员流"')}</div>`,'','panel')}</div></div>`}
function database(){return heading('警情数据库问答','自然语言明确口径，只读查询先检查schema，再解释统计结果。',btn('新建警情问答','start-db','','primary','database'),'专项分析 / Doris NL2SQL 交互预览')+`<div class="split"><div class="panel"><form id="sql-form">${field('自然语言问题','question',state.dbQuestion||'统计近30天各类别警情数量','text','required')}${area('只读SQL（本地语法与危险语句检查，不连接数据库）','sql',state.sql,'required rows="6" class="mono"')}<div class="grid-2">${field('开始日期','start','2026-08-20','date','required')}${field('结束日期','end','2026-09-19','date','required')}</div><div class="form-error" role="alert"></div><div class="actions"><button class="btn primary" type="submit">检查并执行模拟查询</button>${btn('根据问题生成SQL','generate-sql')}</div></form></div><div class="panel">${section('允许访问的schema',kv({'表':'demo_alerts（合成）','主键':'alert_id','字段':'category, occurred_at, region','范围':'演示辖区 · 脱敏字段','权限':'只读，禁止写操作与多语句'}))}${section('统计口径',`<p class="small">COUNT(DISTINCT alert_id)，按类别分组；UTC+8，开始日期含、结束日期次日不含。总量与分组和需一致。</p>`)}</div></div><div class="spacer"></div>${state.sqlExecuted?section('查询结果',table(['类别','去重数量','占比'],[['涉网线索','82','44.57%'],['资金线索','62','33.70%'],['其他线索','40','21.74%'],['合计','184','约100%（四舍五入）']])+`<div class="table-footer">校验：82 + 62 + 40 = 184 · 查询耗时仅为演示 ${badge('总量核验通过')}</div><div class="spacer"></div><div class="actions">${btn(state.querySaved?'查询已收藏':'保存查询条件','save-query',state.querySaved?'disabled':'')}${btn('导出结果CSV','export-query','','secondary','download')}${btn('继续分析此结果','follow-result','data-type="警情问答"')}${btn('生成报告','generate-report','data-type="警情问答"','primary')}</div>`):empty('等待执行只读查询','本地检查通过后显示合成结果，不会访问实际数据库。')}`}
function caseList(){let list=state.cases.filter(c=>!state.caseFilter||c.name.includes(state.caseFilter)||c.number.includes(state.caseFilter));return heading('因案研判','以正式案件引用为上下文，研判任务和成果保持独立版本。',tag('R2 交互预览','blue'))+note('案件均为合成示例。原型不新建正式案件，不向案件主系统写回。')+`<form class="filter-bar" id="case-filter">${field('案件名称或编号','query',state.caseFilter||'','search','placeholder="搜索已授权案件"')}<button class="btn" type="submit">筛选</button>${btn('清空','clear-case-filter')}</form>`+table(['案件','类别','业务状态','负责人','更新日期','操作'],list.map(c=>[`<strong>${esc(c.name)}</strong><p class="small">${c.number}</p>`,c.category,badge(c.status),c.owner,c.updated,btn('进入研判','open-case',`data-id="${c.id}"`,'small primary')]))}
function caseDetail(){const c=state.cases.find(x=>x.id===state.selectedCase)||state.cases[0];if(!c)return '';return heading(esc(c.name),`${c.number} · 案件来源：合成案件系统引用`,btn('从此案件发起研判','case-search',`data-id="${c.id}"`,'primary','search'),'因案研判 / 详情')+`<div class="split"><div>${section('案件上下文',kv({'业务状态':badge(c.status),'授权组织':esc(c.owner),'关联实体':state.entities.slice(0,2).map(e=>btn(esc(e.name),'entity',`data-id="${e.id}"`,'small')).join(' '),'上下文规则':'仅新任务使用所选案件；历史任务归属不变。'}),'','panel')}${section('关联成果',c.reports.length?table(['报告版本','关联时间','操作'],c.reports.map(r=>[esc(r.title)+' / v'+r.version,r.time,btn('查看冻结版本','case-report',`data-id="${c.id}" data-report="${r.id}" data-version="${r.version}"`,'small')])):empty('暂无关联成果','先完成研判并确认要关联的报告版本。',btn('关联已有报告','link-report',`data-id="${c.id}"`)),btn('关联报告版本','link-report',`data-id="${c.id}"`,'small'))}</div><div>${section('成员与权限',c.members.map(m=>`<div class="summary-line"><span>${esc(m)}</span>${tag(m.includes('复核')?'复核':'研判')}</div>`).join('')+`<div class="spacer"></div>${btn('管理成员','case-members',`data-id="${c.id}"`)}<p class="small muted inset">成员变更仅模拟案件范围授权，不修改IDAAS身份主数据。</p>`,'','panel')}${section('研判材料',state.files.slice(0,2).map(fileRow).join(''),'','panel')}</div></div>`}
function eventList(){return heading('因事研判','从线索到任务：先建档、再确认采集，业务状态与执行状态分开。',btn('新建因事任务','new-event','','primary','plus'),'R2 交互预览')+`<form class="filter-bar" id="event-filter">${field('任务名称','query',state.eventFilter||'','search','placeholder="搜索因事任务"')}${select('业务状态','status',['全部','待研判','研判中','已归档'],state.eventStatus||'全部')}<button class="btn" type="submit">筛选</button>${btn('清空','clear-event-filter')}</form>`+table(['任务','类型','业务状态','执行状态','更新时间','操作'],state.events.filter(e=>(!state.eventFilter||e.name.includes(state.eventFilter))&&(!state.eventStatus||state.eventStatus==='全部'||e.business===state.eventStatus)).map(e=>[esc(e.name),e.type,badge(e.business),badge(e.execution),e.updated,btn('进入详情','open-event',`data-id="${e.id}"`,'small primary')]))}
function wizard(){const w=state.wizard;return heading('新建因事任务','填写目标和实体线索，选择授权工具；保存草稿不会执行采集。',btn('保存草稿并返回','save-wizard'),'因事研判 / 创建向导')+`<div class="panel">${steps(['基本信息','实体线索','采集工具'],w.step-1)}<form id="wizard-form">${w.step===1?`<div class="grid-2">${field('任务名称 *','name',w.name,'text','required maxlength="80"')}${select('研判类型 *','type',['线索核查','资金分析','人员分析'],w.type)}${field('创建人','creator',state.user,'text','readonly')}${field('所属组织','org',state.org,'text','readonly')}</div>${select('是否已立案','registered',['否','是'],w.registered)}<div id="case-field" ${w.registered==='是'?'':'hidden'}>${select('已授权案件（已立案时必选）','caseId',['请选择',...state.cases.map(c=>c.id)],w.caseId||'请选择')}</div>`:w.step===2?note('最多5个初始实体。角色来自资料或人工标注，不能由模型自动定性。')+state.entities.map(e=>check(`${esc(e.name)} · ${e.type} · ${esc(e.identifier)}`,'entities',w.entities.includes(e.id),`value="${e.id}"`)).join('')+btn('新增合成实体','add-entity','','secondary','plus'):`${note('完成后只创建任务。进入详情并确认采集后才执行，未授权工具会被阻断。')}${state.tools.map(t=>check(`${esc(t.name)} · v${t.version} · ${esc(t.permission)}`,'tools',w.tools.includes(t.id),`value="${t.id}" ${t.status!=='已发布'?'disabled':''}`)).join('')}<div class="receipt inset">${kv({'任务':esc(w.name),'类型':esc(w.type),'实体数':w.entities.length+'个','案件':esc(w.registered==='是'?w.caseId:'未立案，不要求虚填案件号')})}</div>`}<div class="form-error" role="alert"></div><div class="form-actions"><div>${w.step>1?btn('上一步','wizard-prev'):link('返回列表','PG14','btn')}</div><button type="submit" class="btn primary">${w.step===3?'创建任务（不执行）':'保存并下一步'} ${icon('arrow')}</button></div></form></div>`}
function eventDetail(){const e=state.events.find(x=>x.id===state.selectedEvent)||state.events[0];return heading(esc(e.name),`${e.id} · ${e.type}`,`<div class="actions">${badge(e.business)}${badge(e.execution)}${btn('确认资料采集','collect-event',`data-id="${e.id}"`,'primary','play')}</div>`,'因事研判 / 详情')+`<div class="grid-2">${section('实体与线索',e.entities.map(id=>state.entities.find(x=>x.id===id)).filter(Boolean).map(x=>`<button class="entity-row" data-action="entity" data-id="${x.id}">${icon('user')}<span class="grow">${esc(x.name)}<p class="small">${esc(x.identifier)}</p></span>${icon('chevron')}</button>`).join('')+`<div class="actions inset">${btn('修改任务元信息','edit-event',`data-id="${e.id}"`)}${btn('围绕线索继续研判','event-search',`data-id="${e.id}"`)}</div>`,'','panel')}${section('研判笔记',e.notes.map(n=>`<div class="receipt inset"><p>${esc(n.text)}</p><small class="muted">${esc(n.time)} · 人工补充</small></div>`).join('')||'<p class="muted small">暂无人工笔记。补充记录不会覆盖原始事实。</p>',btn('添加笔记','event-note',`data-id="${e.id}"`,'small','plus'),'panel')}</div>${section('采集批次',table(['批次','开始时间','执行状态','操作'],e.batches.map(b=>[b.id,b.time,badge(state.sessions.find(s=>s.id===b.session)?statusLabel(state.sessions.find(s=>s.id===b.session)):b.status),btn('查看执行','open-session',`data-id="${b.session}"`,'small')])))}<div class="actions">${link('实体图谱','PG20','btn')}${link('资料结果','PG19','btn')}${btn('生成研判报告','generate-report','','primary')}</div>`}
function serial(){return heading('案件串并','从授权案件集合发现候选关联，人工核验后形成意见，不自动合并正式案件。',tag('R3 交互预览','warning'))+`<form class="filter-bar" id="serial-filter">${select('候选范围','range',['当前授权的2个合成案件'],'当前授权的2个合成案件')}${select('关联规则','rule',['共用账户标识','事件时间窗口','共同实体'],state.serial.rule||'共用账户标识')}<button class="btn primary" type="submit">生成候选</button></form><div class="split"><div class="panel">${section('候选案件对',`<h3>演示网络交易线索 ↔ 演示关联账户核查</h3><div class="spacer"></div>${kv({'关联理由':'相同合成账户标识 DEMO-ACCOUNT-A','反证检查':'需排除共享账户与错误身份映射','当前规则':esc(state.serial.rule||'共用账户标识'),'核验状态':badge(state.serial.status),'复核状态':badge(state.serial.reviewed?'负责人已复核':'未复核')})}`)}<div class="actions">${btn('核验候选','serial-review','','primary')}${btn('负责人复核','serial-approve',state.serial.status==='待核验'?'disabled':'')}${btn('导出串并意见','serial-export',state.serial.reviewed?'':'disabled')}</div></div><div class="panel">${section('两侧证据对照',table(['案件','证据','定位'],[['CASE-0817','合成交易表第2行',btn('查看','evidence','','small')],['CASE-0802','合成账户资料',btn('查看','evidence','','small')]]))}${note('无正式案件系统写回接口。即便意见通过，也只生成串并研判意见，不显示“案件已合并”。','warning')}${state.serial.reason?`<p class="small">核验意见：${esc(state.serial.reason)}</p>`:''}</div></div>`}
function files(){const fs=state.files.filter(f=>f.org===state.org&&(state.fileArchived||!f.archived)&&(!state.fileFilter||f.name.includes(state.fileFilter)));return heading('文档空间','原始材料与派生产物分开管理，版本、血缘和核验状态可追溯。',btn('上传材料','upload','','primary','upload'))+`<form class="filter-bar" id="file-filter">${field('文件名称','query',state.fileFilter||'','search','placeholder="搜索材料或产物"')}${check('包含已归档','archived',state.fileArchived)}<button class="btn" type="submit">筛选</button></form>`+table(['名称','类型与来源','处理状态','版本 / 大小','操作'],fs.map(f=>[`<strong>${esc(f.name)}</strong><p class="small">${esc(f.id)} ${f.archived?'· 已归档':''}</p>`,`${f.raw?'原始材料':'派生产物'}<p class="small">${esc(f.source)}</p>`,badge(f.status),`v${f.version} · ${esc(f.size)}`,`<div class="actions">${btn('预览','preview-file',`data-id="${f.id}"`,'small')}${btn('血缘','file-lineage',`data-id="${f.id}"`,'small')}${btn(f.archived?'还原':'归档','archive-file',`data-id="${f.id}"`,'small')}</div>`]))+`<div class="table-footer">共 ${fs.length} 项 · 归档不等于销毁；原型不提供物理删除。</div>`+note('支持本地 TXT、CSV、JSON（单文件≤2MB）；只做本地解析，不提供真实安全扫描、OCR或ASR。请勿上传真实敏感材料。','warning')}
export function entityView(){const e=state.entities.find(x=>x.id===state.selectedEntity)||state.entities[0];return heading(esc(e.name),`${e.type} · ${e.id}`,tag(e.excluded?'已排除分析':'纳入当前分析',e.excluded?'warning':'blue'))+kv({'稳定标识':esc(e.identifier),'角色来源':esc(e.role),'来源':esc(e.source),'实体消歧':'同名不合并，标识冲突需人工核验','视图状态':e.hidden?'在图谱中隐藏（仍参与分析）':'可见'})+`<div class="spacer"></div>${section('关联证据',btn('查看原始来源','evidence','','secondary','file'))}${section('人工标注',e.notes.map(n=>`<div class="receipt inset">${esc(n.text)}<p class="small">${esc(n.reason)} · ${esc(n.time)}</p></div>`).join('')||'<p class="muted">暂无人工补充。</p>')}<div class="actions">${btn('补充人工标注','entity-note',`data-id="${e.id}"`,'primary')}${btn(e.hidden?'恢复显示':'隐藏此节点','hide-entity',`data-id="${e.id}"`)}${btn(e.excluded?'恢复纳入分析':'排除分析范围','exclude-entity',`data-id="${e.id}"`,'danger')}</div>${note('人工补充保留原始来源。隐藏只影响当前视图；排除分析必须填写原因，并生成范围版本。')}`}
export function evidence(){const f=state.files.find(f=>f.id===state.selectedFile)||state.files[0];return heading('证据来源核验',`${esc(f.name)} · ${f.id} · v${f.version}`,badge(f.status),'引用 [证据01] / 原文定位')+note('原型演示的“证据”表示可追溯来源引用，不意味着已满足法定证据要求。')+kv({'采集来源':esc(f.source),'来源任务':esc(f.session),'内容类型':f.raw?'原始材料':'派生产物','引用定位':f.type==='CSV'?'第2行 · 原始记录':'第1段 · 合成文本','转换链':'原始对象 → 结构化预览 → 结论引用'})+`<div class="spacer"></div><pre class="code">${esc(f.content)}</pre><div class="actions inset">${btn('标记已核验','verify-evidence',`data-id="${f.id}"`,'primary')}${btn('记录反证或缺口','evidence-note',`data-id="${f.id}"`)}${btn('模拟引用失效','invalidate-evidence',`data-id="${f.id}"`,'danger')}</div>${f.verified?note('已记录人工核验意见；不自动将全部报告变为已复核。'):''}${f.invalid?note('引用锚点已失效。依赖此来源的报告需重新核验，不允许导出为已复核完整报告。','danger'):''}${f.verificationNote?`<div class="receipt inset">核验意见：${esc(f.verificationNote)}</div>`:''}`}
function timeline(){return heading('事件时间线','并列展示原始来源和标准化时间，冲突不被自动消除。',btn('查看时空冲突','conflict','','primary'))+note('统一展示UTC+8，原始时区记录保留。未知时间不补默认日期，地点精度需分别核验。')+`<div class="panel timeline">${[['2026-09-03 10:20','演示地点C活动记录','来源S03 · 城区级精度 · 标准化时间'],['2026-09-03 10:25','演示地点D活动记录','来源S04 · 场所级精度 · 与上一记录存在冲突'],['2026-09-04 15:30','演示账户A到商户B的交易','来源S02 · 资金事实，不推断人员位置']].map(([d,t,b])=>`<div class="timeline-item"><small>${d} UTC+8</small><h3>${t}</h3><p>${b}</p><div class="actions inset">${btn('来源定位','evidence','','small')}${btn('记录核验','conflict','','small')}</div></div>`).join('')}</div>${state.conflictNote?note('人工冲突核验：'+esc(state.conflictNote)):''}`}
function reports(){const r=state.reports.find(x=>x.id===state.selectedReport)||state.reports[0];return heading('研判报告','保存形成新版本，提交复核冻结该版本；来源更新不静默改写已保存报告。',`<div class="actions">${badge(r.status)}${btn('预览与版本','report-preview','','secondary','file')}${btn('复核与导出','go-review','','primary','download')}</div>`,'成果 / '+esc(r.id))+`<div class="split"><div class="panel"><form id="report-form">${field('报告标题','title',r.title,'text','required maxlength="120"')}${area('正文（事实、推断、缺口分别陈述）','content',r.content,'required class="report-editor"')}<div class="form-error" role="alert"></div><div class="actions"><button class="btn primary" type="submit">保存为 v${r.version+1}</button>${btn('提交当前版本复核','submit-review',r.status==='待复核'?'disabled':'')}${btn('核验引用','evidence')}</div></form></div><div>${caseReportPreview(r)}${section('报告状态',kv({'当前版本':'v'+r.version,'复核状态':badge(r.status),'作者':esc(r.author),'关联案件':esc(r.caseId||'未关联'),'来源任务':esc(r.session),'引用有效性':state.files.some(f=>(r.sourceIds||['OBJ-001']).includes(f.id)&&f.invalid)?badge('引用异常'):badge('待人工确认')}),'','panel')}${r.feedback?note('复核意见：'+esc(r.feedback),'warning'):''}${section('版本记录',r.history.length?r.history.slice().reverse().map(v=>`<div class="summary-line"><div>v${v.version}<p class="small">${esc(v.time)}</p></div>${btn('预览','report-version',`data-version="${v.version}"`,'small')}</div>`).join(''):'<p class="small muted">保存后保留此前版本。</p>','','panel')}${section('核验清单',check('确认统计口径及来源范围','report-check-1',!!state.checks['report-check-1'])+check('事实与推断已分开陈述','report-check-2',!!state.checks['report-check-2'])+check('数据缺口与限制已披露','report-check-3',!!state.checks['report-check-3']),'','panel')}</div></div>`}
export function review(){const r=state.reports.find(x=>x.id===state.selectedReport)||state.reports[0];return (r.caseId?btn('返回报告编辑','case-review-back','','small'):'')+heading('复核与导出',`${esc(r.title)} · 当前版本 v${r.version}`,badge(r.status),'成果流转 / R1导出 · R2复核')+`<div class="grid-2"><div class="panel">${section('人工复核',kv({'作者':esc(r.author),'待复核版本':r.reviewVersion?'v'+r.reviewVersion:'尚未提交','状态':badge(r.status),'角色要求':'业务负责人，且不能自审自己的报告'}))}<div class="actions">${btn('提交当前版本','submit-review',r.status==='待复核'?'disabled':'')}${btn('复核通过','review-pass',r.status==='待复核'?'':'disabled','primary')}${btn('退回修改','review-reject',r.status==='待复核'?'':'disabled','danger')}</div>${r.feedback?`<p class="small inset">${esc(r.feedback)}</p>`:''}</div><div class="panel"><form id="export-report-form">${select('导出格式','format',['TXT（正文）','JSON（含来源元信息）'],'TXT（正文）')}${select('导出范围','range',['当前保存版本'],'当前保存版本')}${select('脱敏方式','mask',['保留合成标识，不导出身份字段'],'保留合成标识，不导出身份字段')}${field('导出用途 *','purpose','','text','required maxlength="100" placeholder="填写本次导出的用途"')}${check('已理解数据缺口及复核状态会随文件导出','confirm',false,'required')}<div class="form-error" role="alert"></div><button type="submit" class="btn primary">生成导出文件 ${icon('download')}</button></form></div></div><div class="spacer"></div>${note('原型仅生成TXT/JSON，不冒充PDF或DOCX。未经复核的报告带明确状态；下载前重新检查本地演示身份与引用状态。')}`}
function applications(approval=false){const list=state.applications.filter(a=>(a.org||'演示研判一组')===state.org&&(approval||a.applicant===state.user));return heading(approval?'审批待办':'我的申请',approval?'核对申请范围、期限和用途，审批通过后不自动恢复已终止动作。':'申请仅限明确对象与时间范围，重复未决申请复用。',approval?tag('R2 审批演示','warning'):btn('新建访问申请','apply-permission','','primary','plus'))+table(['申请','范围与用途','申请人','状态','操作'],list.map(a=>[esc(a.name),`${esc(a.range)}<p class="small">${esc(a.purpose)}</p>`,esc(a.applicant),badge(a.status),`<div class="actions">${btn('详情','application-detail',`data-id="${a.id}"`,'small')}${approval?btn('审批','application-review',`data-id="${a.id}" ${a.status==='待审批'?'':'disabled'}`,'small primary'):btn(a.status==='已批准'?'检查并继续':'撤回','application-act',`data-id="${a.id}" ${['待审批','已批准'].includes(a.status)?'':'disabled'}`,'small')}</div>`]))+note('审批员不可审批自己的申请。真实审批引擎、授权传播与恢复合同仍需后端评审；本页用于完整链路演示。')}
function notifications(){return heading('通知与任务更新','通知只提示状态变化；打开时重验当前权限，不直接展示敏感内容。',btn('全部标为已读','read-all'))+`<div class="panel">${state.notices.length?state.notices.map(n=>`<div class="notification-item ${n.read?'read':''}"><span class="status-symbol">${icon(n.route==='PG27'?'shield':'bell')}</span><div class="grow"><h3>${esc(n.title)} ${n.read?'':tag('未读','blue')}</h3><p>${esc(n.description)}</p></div>${btn('查看','open-notice',`data-id="${n.id}"`,'small')}</div>`).join(''):empty('没有新的通知','任务完成、审批变化和导出就绪时会在这里提示。')}</div>`}
function identity(){return heading('用户组织与权限','身份主数据来自IDAAS。原型只模拟角色和组织上下文，不建立第二套身份系统。',btn('调整演示上下文','profile','','primary','user'))+`<div class="grid-2">${section('当前身份',kv({'用户':esc(state.user),'组织':esc(state.org),'角色':tag(state.role,'blue'),'身份状态':badge(state.loggedIn?'演示身份有效':'未登录'),'业务访问':state.permission?'按当前角色展示':'权限已撤回'}),'','panel')}${section('授权边界',`<p class="small">身份有效 ∩ 组织范围 ∩ 案件范围 ∩ 数据源权限 ∩ 操作权限</p><div class="spacer"></div>${note('平台管理员可以配置工具，但不会自动获得案件内容权限。切换组织会断开旧订阅并清理当前选择。')}<div class="actions">${btn('模拟令牌过期','expire','','danger')}${btn(state.permission?'模拟权限撤回':'恢复演示访问','toggle-permission','','secondary')}${btn('退出演示','logout')}</div>`,'','panel')}</div>${section('角色映射参考',table(['角色','主要能力','不能默认执行'],[['研判人员','查询、分析、报告草稿','自审报告、配置发布'],['业务负责人','成果复核、范围协作','超授权数据访问'],['审批人员','职责内访问申请审批','自批申请'],['平台管理员','工具和Agent配置','读取案件正文'],['安全审计人员','脱敏审计与诊断','修改业务事实']]))}`}
function tools(){return heading('工具目录','schema、权限和副作用作为工具契约，测试通过后才能发布。',btn('新建工具草稿','new-tool','','primary','plus'))+table(['工具','类别','版本','状态','权限 / 副作用','操作'],state.tools.map(t=>[`<strong>${esc(t.name)}</strong><p class="mono">${esc(t.id)}</p>`,t.category,'v'+t.version,badge(t.status),`${esc(t.permission)}<p class="small">${esc(t.sideEffect)}</p>`,`<div class="actions">${btn('配置','tool-config',`data-id="${t.id}"`,'small primary')}${btn('版本回滚','tool-rollback',`data-id="${t.id}" ${t.history.length?'':'disabled'}`,'small')}${btn(t.status==='已禁用'?'恢复草稿':'禁用','tool-disable',`data-id="${t.id}"`,'small')}</div>`]))+`<div class="spacer"></div>${note('凭据只允许 secret:// 引用；禁止在原型录入真实令牌。测试为本地schema契约检查，不表示外部接口连通。')}`}
function config(){const c=state.config;return heading('项目与 Agent 配置','每次发布形成版本；在途执行保留启动时的工具与配置快照。',tag('当前配置 v'+c.version,'blue'))+`<div class="split"><div class="panel"><form id="config-form">${field('模型适配器','model',c.model,'text','required') }<div class="grid-3">${field('并发上限','concurrency',c.concurrency,'number','required min="1" max="10"')}${field('重试次数','retries',c.retries,'number','required min="0" max="3"')}${field('超时秒数','timeout',c.timeout,'number','required min="10" max="300"')}</div><h3>关联工具集</h3>${state.tools.map(t=>check(`${esc(t.name)} / v${t.version}`,'tools',c.tools.includes(t.id),`value="${t.id}" ${t.status==='已发布'?'':'disabled'}`)).join('')}<div class="form-error" role="alert"></div><div class="actions"><button class="btn" type="submit">保存并检查配置</button>${btn('发布新版本','publish-config',c.tested?'':'disabled','primary')}${btn('回滚上一版本','rollback-config',c.history.length?'':'disabled')}</div></form></div><div class="panel">${section('检查与发布',kv({'契约检查':badge(c.tested?'检查通过':'未检查'),'关联数量':c.tools.length+'个','调度策略':'按依赖调度，简单/复杂问题分流','版本隔离':'新任务采用新配置；在途任务不变'}))}${section('版本历史',c.history.map(x=>`<div class="summary-line">v${x.version}<span class="small muted">${esc(x.time)}</span></div>`).join('')||'<p class="small muted">首次发布后产生版本记录。</p>')}</div></div>`}
function audits(){const list=state.audits.filter(a=>!state.auditFilter||a.action.includes(state.auditFilter)||a.object.includes(state.auditFilter));return heading('审计与运行诊断','记录查询、授权、导出和配置变更。仅显示脱敏摘要，不暴露凭据或原始推理。',btn('导出审计JSON','export-audit','','secondary','download'))+`<form class="filter-bar" id="audit-filter">${field('动作或对象','query',state.auditFilter||'','search','placeholder="搜索审计事件"')}<button type="submit" class="btn">筛选</button>${btn('清空','clear-audit-filter')}</form>`+table(['时间','角色','动作','对象','结果','关联轨迹'],list.slice(0,30).map(a=>[esc(a.time),esc(a.actor),esc(a.action),esc(a.object),badge(a.result),btn('诊断','audit-detail',`data-id="${a.id}"`,'small')]))+`<div class="table-footer">共 ${list.length} 条 · 当前展示最近30条 ${tag('本地演示日志')}</div>`}
function memories(){return heading('经验与偏好','候选经验经脱敏、适用性和反例评测后发布，不自动全局生效。',btn('新增候选经验','new-memory','','primary','plus'),'R2 治理交互预览')+`<div class="panel">${section('用户偏好',check('保存本地界面偏好','pref-save',state.preferences.save)+check('紧凑的表格行高','pref-compact',state.preferences.compact)+btn('清除本地偏好','clear-preferences','','small'))}</div><div class="spacer"></div>`+table(['候选经验','适用范围','评测','版本与状态','操作'],state.memories.map(m=>[esc(m.name),esc(m.scope),badge(m.evaluated?'模拟用例通过':'尚未评测'),`v${m.version} ${badge(m.status)}`,`<div class="actions">${btn('详情','memory-detail',`data-id="${m.id}"`,'small')}${btn('评测','evaluate-memory',`data-id="${m.id}"`,'small')}${btn(m.status==='已发布'?'下线':'审核发布','publish-memory',`data-id="${m.id}" ${m.evaluated?'':'disabled'}`,'small primary')}</div>`]))+note('评测仅检查原型用例与字段完整性，不代表真实模型效果。禁止将真实案件材料写入跨用户共享经验。')}
function skills(){return heading('Skills 目录','能力包结构与治理交互预览；技术方案明确本期不启用运行时加载。',tag('R3 · 不在首期运行','warning'))+note('此模块未遗漏：提供目录、文件、版本及变更预览，但不会启用或执行Skills。必须完成DEC11评审后才能接入真实运行时。','warning')+state.skills.map(s=>section(esc(s.name),`<p>${esc(s.description)}</p><div class="spacer"></div>${kv({'版本':'v'+s.version,'状态':badge(s.status),'权限声明':esc(s.permission),'文件':s.files.map(esc).join('、'),'运行时':'未接入；不会注入当前任务'})}<div class="actions inset">${btn('查看能力包','skill-detail',`data-id="${s.id}"`)}${btn('保存设计草稿','skill-edit',`data-id="${s.id}"`)}${btn('检查设计契约','skill-check',`data-id="${s.id}"`)}${btn('发布设计版本','skill-publish',`data-id="${s.id}" ${s.checked?'':'disabled'}`)}${btn('停用设计版本','skill-disable',`data-id="${s.id}"`)}${btn('版本与调用记录','skill-history',`data-id="${s.id}"`)}${btn('启用运行时','unsupported-skill','disabled title="当前技术范围不支持"')}</div>`,'','panel')).join('')}
function login(){return `<main id="main" class="login-page"><div class="panel login-box"><img class="brand-mark" src="/assets/brand/logo.svg" alt=""><h1>研判助手</h1><p>统一身份入口 · IDAAS / EasyGateway<br>这是本地交互原型，不收集密码或真实身份信息。</p>${state.identityError!=='正常'?note(esc(state.identityError)+'。重新建立演示身份后读取已有快照，不重发工具动作。','warning'):''}<form id="login-form">${select('演示身份状态','identityError',['正常','登录超时','账号异常','无应用权限','终端不符','令牌已过期'],state.identityError)}<div class="form-error" role="alert"></div><button class="btn primary full" type="submit">进入演示工作台 ${icon('arrow')}</button></form><p class="small inset">只读合成数据。未授权时不显示任何业务预览。</p></div></main>`}
export function pageContent(id){switch(id){case'PG02':return overview();case'PG03':return drill();case'PG06':return history();case'PG08':return execution();case'PG09':return fund();case'PG10':return person();case'PG11':return database();case'PG12':return caseListPage();case'PG13':return casePage(caseDetail());case'PG14':return eventList();case'PG15':return wizard();case'PG16':return eventDetail();case'PG17':return serial();case'PG18':return heading('执行工作空间','同一个任务快照驱动计划、过程和产物。',link('返回超级搜索','PG05','btn'))+`<div class="workspace-overview"><div class="panel right-in-modal">${workspace()}</div><div class="panel workspace-execution">${execution()}</div></div>`;case'PG19':return files();case'PG20':return heading('导图空间','来源事实、待核验推断与人工补充分层呈现，修改保留版本。',link('时间线','PG23','btn'))+graph()+`<div class="legend"><span>— 来源事实</span><span>┄ 待核验推断</span><span>人工补充独立标注</span></div><div class="spacer"></div>`+table(['关系','来源类型','依据','操作'],state.relations.map(r=>[esc(r.type),tag(r.source),esc(r.reason),btn('详情与修改','relation',`data-id="${r.id}"`,'small')]));case'PG21':return `<div class="panel">${entityView()}</div>`;case'PG22':return `<div class="panel">${evidence()}</div>`;case'PG23':return timeline();case'PG24':return reports();case'PG25':return review();case'PG26':return applications();case'PG27':return applications(true);case'PG28':return notifications();case'PG29':return identity();case'PG30':return tools();case'PG31':return config();case'PG32':return audits();case'PG33':return memories();case'PG34':return skills();default:return empty('页面不存在','请从功能总览选择一个已定义页面。',btn('功能总览','coverage'))}}
export function renderPage(id){const h=header(id);if(id==='PG01'||!state.loggedIn)return h+login();if(denied(id))return h+`<div class="app-layout">${sidebar(id)}<main id="main" class="main-page">${heading(titleFor(id))}${permissionPage()}</main></div>`;if(['PG12','PG13'].includes(id))return h+`<main id="main" class="case-main">${state.viewState!=='正常'?heading(titleFor(id))+genericState():pageContent(id)}</main>`;if(['PG04','PG05','PG07'].includes(id)&&state.viewState==='正常')return h+workbench(id);return h+`<div class="app-layout">${sidebar(id)}<main id="main" class="main-page">${state.viewState!=='正常'?heading(titleFor(id))+genericState():pageContent(id)}</main></div>`}
export function coverage(){return note('每个条目都可以进入对应页面。R2/R3也纳入原型；标为受限的能力需切换演示角色，后端能力仍为模拟。')+`<div class="tabs"><button class="active" data-action="coverage-tab" data-tab="pages">34 页面</button><button data-action="coverage-tab" data-tab="features">67 功能点</button><button data-action="coverage-tab" data-tab="flows">22 交互链路</button></div><div class="spacer"></div><div id="coverage-content">${coverageContent('pages')}</div>`}
export function coverageContent(type){if(type==='pages')return `<div class="coverage-grid">${pages.map(p=>`<div class="coverage-item"><small>${p.id} · ${esc(p.basis)}</small><strong>${esc(p.name)}</strong>${btn('打开页面','coverage-route',`data-route="${p.id}"`,'small')}</div>`).join('')}</div>`;if(type==='features')return `<div class="coverage-grid">${features.map(f=>`<div class="coverage-item"><small>${f.id} → ${routeForFeature(f.id)}</small><strong>${esc(f.name)}</strong>${btn('需求与原型入口','feature-detail',`data-id="${f.id}"`,'small')}</div>`).join('')}</div>`;return `<div class="stack">${flows.map((f,i)=>`<div class="coverage-item"><small>${f.id}</small><strong>${esc(f.name)}</strong><p class="small">${esc(f.requirement)}</p>${btn('从链路起点开始','flow-start',`data-index="${i}"`,'small')}</div>`).join('')}</div>`}
